import{_ as e,o,c as r,a2 as n}from"./chunks/framework.DHtetOlu.js";const p=JSON.parse('{"title":"Geometry (CAD)","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/geometry.md","filePath":"en/guide/geometry.md"}'),d={name:"en/guide/geometry.md"};function a(i,t,s,c,l,h){return o(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="geometry-cad" tabindex="-1">Geometry (CAD) <a class="header-anchor" href="#geometry-cad" aria-label="Permalink to &quot;Geometry (CAD)&quot;">​</a></h1><p>The MagFEM drawing is <strong>parametric</strong>, in the style of Onshape: you sketch freely and then lock the shape with <strong>constraints</strong> (horizontal, tangent, coincident…) and <strong>dimensions</strong> (distances, radii, angles). Dimensions accept units and expressions with variables, so changing a variable redraws the whole model. The constraint solver is PlaneGCS, the same one used by FreeCAD.</p><h2 id="drawing-tools" tabindex="-1">Drawing tools <a class="header-anchor" href="#drawing-tools" aria-label="Permalink to &quot;Drawing tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Key</th><th>Use</th></tr></thead><tbody><tr><td>Select</td><td><code>S</code> or <code>Esc</code></td><td>click selects, Shift adds; drag to move</td></tr><tr><td>Measure (ruler)</td><td><code>U</code></td><td>two clicks measure a distance; does not change the drawing</td></tr><tr><td>Line / polyline</td><td><code>L</code></td><td>each click continues the polyline; ends when closing on an existing point, on a double-click or with <code>Esc</code></td></tr><tr><td>Construction line</td><td><code>Shift+L</code></td><td>helper line: guides the drawing but does not form regions</td></tr><tr><td>Rectangle</td><td><code>R</code></td><td>two opposite corners (created as a group, with H/V)</td></tr><tr><td>Center rectangle</td><td><code>Shift+R</code></td><td>center and one corner (symmetric about the center)</td></tr><tr><td>Circle</td><td><code>C</code></td><td>center and a point on the edge</td></tr><tr><td>Three-point arc</td><td><code>A</code></td><td>start, end and a point on the arc</td></tr><tr><td>Center arc</td><td><code>Shift+A</code></td><td>center, start and end (the mouse movement picks the direction)</td></tr><tr><td>Point</td><td><code>P</code></td><td>free point (handy as a dimension reference)</td></tr></tbody></table><p>Buttons with a small arrow group variants (line/construction, rectangle/center, three-point/center arc); the button shows the last variant used.</p><h2 id="snapping" tabindex="-1">Snapping <a class="header-anchor" href="#snapping" aria-label="Permalink to &quot;Snapping&quot;">​</a></h2><p>While drawing, the cursor snaps, in this order, to:</p><ol><li>existing <strong>points</strong> (end points, centers, the Origin): the new point becomes that same point;</li><li>line <strong>midpoints</strong>: adds a &quot;midpoint&quot; constraint;</li><li><strong>curves</strong>: adds &quot;point on curve&quot;;</li><li>the <strong>x and y axes</strong> (r and z in axisymmetric problems): adds a vertical or horizontal constraint to the Origin.</li></ol><p>For lines, the second point also infers <strong>horizontal or vertical</strong> when it is nearly aligned, and snaps to where that direction crosses the nearest curve. All these constraints show up in the tree (<strong>Geometry › Constraints</strong>) and can be deleted.</p><div class="tip custom-block"><p class="custom-block-title">The Origin</p><p>Clicking the origin creates a point of its own with a <strong>Coincident</strong> constraint to the Origin. To free the part, delete that constraint. Older drawings where a curve uses the Origin itself show <strong>Detach from origin</strong> in the properties panel.</p></div><h2 id="constraints" tabindex="-1">Constraints <a class="header-anchor" href="#constraints" aria-label="Permalink to &quot;Constraints&quot;">​</a></h2><p>Select the entities and click the constraint button (or press its key).</p><table tabindex="0"><thead><tr><th>Constraint</th><th>Key</th><th>Entities</th></tr></thead><tbody><tr><td>Coincident</td><td><code>I</code></td><td>two points, or a point and a curve (point on)</td></tr><tr><td>Horizontal / Vertical</td><td><code>H</code> / <code>V</code></td><td>a line, or two points</td></tr><tr><td>Parallel / Perpendicular</td><td></td><td>two lines</td></tr><tr><td>Tangent</td><td><code>T</code></td><td>a line and an arc/circle, or two arcs/circles</td></tr><tr><td>Equal</td><td><code>E</code></td><td>two lines (length) or two arcs/circles (radius)</td></tr><tr><td>Midpoint</td><td><code>M</code></td><td>a point and a line</td></tr><tr><td>Symmetric</td><td></td><td>two points and an axis (line)</td></tr><tr><td>Concentric</td><td></td><td>two arcs/circles</td></tr><tr><td>Fix</td><td></td><td>pins points at their current position</td></tr></tbody></table><p>The color shows the state: <strong>blue</strong> still has degrees of freedom, <strong>black</strong> (white in the dark theme) is fully defined. The status bar shows how many degrees of freedom remain. A constraint that conflicts with the others is refused, with a message in the status bar.</p><h2 id="dimensions-and-variables" tabindex="-1">Dimensions and variables <a class="header-anchor" href="#dimensions-and-variables" aria-label="Permalink to &quot;Dimensions and variables&quot;">​</a></h2><p>With the <strong>Dimension</strong> tool (<code>D</code>), click an entity (or two) and then where you want the text; type the value.</p><ul><li>A line or two points give a distance; the text position picks the <strong>aligned</strong>, <strong>horizontal</strong> or <strong>vertical</strong> distance.</li><li>A circle gives the diameter; an arc gives the radius; two lines give an angle; a point and a line give the point-to-line distance.</li><li>The value accepts a number (in the project unit), a number with a unit (<code>2 cm</code>, <code>0.5 in</code>) or an expression with variables (<code>Ds/2 - g</code>).</li></ul><p>Variables live under <strong>Geometry › Variables</strong> (<code>+</code> creates one). Double-clicking a dimension edits its value.</p><h2 id="editing" tabindex="-1">Editing <a class="header-anchor" href="#editing" aria-label="Permalink to &quot;Editing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Key</th><th>Description</th></tr></thead><tbody><tr><td>Trim</td><td><code>X</code></td><td>click a piece of a curve to remove it, up to the nearest intersections. At an end it shortens the curve; in the middle it splits it in two; a cut circle becomes an arc; a curve with no crossings is deleted</td></tr><tr><td>Offset</td><td><code>O</code></td><td>parallel copy at a distance (associative: follows the original)</td></tr><tr><td>Mirror</td><td></td><td>reflects the selection about a line or axis</td></tr><tr><td>Linear / circular pattern</td><td></td><td>copies in a grid or around a center</td></tr><tr><td>Move / rotate</td><td><code>G</code></td><td>translates and rotates the selection by typed values</td></tr><tr><td>Group / Ungroup</td><td><code>Ctrl+G</code> / <code>Ctrl+Shift+G</code></td><td>a group is selected and moved as one part; double-click enters the group to edit an entity</td></tr><tr><td>Construction</td><td><code>Q</code></td><td>toggles a curve between normal and construction</td></tr><tr><td>Delete</td><td><code>Del</code></td><td>deletes the selection</td></tr><tr><td>Fit</td><td><code>F</code></td><td>frames the drawing</td></tr><tr><td>Undo / Redo</td><td><code>Ctrl+Z</code> / <code>Ctrl+Shift+Z</code> (or <code>Ctrl+Y</code>)</td><td></td></tr></tbody></table><p>Offset, mirror and patterns are <strong>associative</strong>: the copy follows the original when it changes, and the distance or the number of copies stays editable in the properties.</p><h2 id="box-selection" tabindex="-1">Box selection <a class="header-anchor" href="#box-selection" aria-label="Permalink to &quot;Box selection&quot;">​</a></h2><p>As in CAD programs, dragging a box <strong>to the right</strong> selects what lies entirely inside it; dragging <strong>to the left</strong> selects everything it touches.</p><h2 id="planar-and-axisymmetric" tabindex="-1">Planar and axisymmetric <a class="header-anchor" href="#planar-and-axisymmetric" aria-label="Permalink to &quot;Planar and axisymmetric&quot;">​</a></h2><p>In the <strong>Problem and libraries</strong> drawer, choose the problem type and the length <strong>unit</strong>:</p><ul><li><strong>Planar</strong>: x and y; set the <strong>depth</strong> (length along z), used for flux linkage, energy and force.</li><li><strong>Axisymmetric</strong>: r (horizontal) and z (vertical), with the symmetry axis at r = 0. Only the r ≥ 0 half-plane counts; it is highlighted and MagFEM warns when something is drawn at r &lt; 0.</li></ul><h2 id="importing-geometry" tabindex="-1">Importing geometry <a class="header-anchor" href="#importing-geometry" aria-label="Permalink to &quot;Importing geometry&quot;">​</a></h2><p><strong>Import</strong> accepts DXF and SVG: curves are added to the drawing and coincident points are merged so regions close. See also <a href="./files.html">Files, import and export</a>.</p>',28)])])}const m=e(d,[["render",a]]);export{p as __pageData,m as default};
